def round_report(rounds):
    totals = []
    for row in rounds:
        total = 0
        for value in row:
            total += value
        totals.append(total)
    leaders = sorted(totals, reverse=True)[:3]
    return totals, leaders

print(round_report([[3, -1], [], [4, 2], [1]]))
